questions.starter_code:
function map(array, callback) {
  // Return a new array of callback(item, index, array) for each item.
}

questions.solution:
function map(array, callback) {
  const result = [];
  for (let i = 0; i < array.length; i++) {
    result.push(callback(array[i], i, array));
  }
  return result;
}

questions.starter_code:
function filter(array, callback) {
  // Return a new array of the items where callback(item, index, array) is truthy.
}

questions.solution:
function filter(array, callback) {
  const result = [];
  for (let i = 0; i < array.length; i++) {
    if (callback(array[i], i, array)) result.push(array[i]);
  }
  return result;
}

questions.starter_code:
function reduce(array, callback, initial) {
  // Combine the items into one value with callback(acc, item, index, array).
}

questions.solution:
function reduce(array, callback, ...rest) {
  let i = 0;
  let acc;
  if (rest.length > 0) {
    acc = rest[0];
  } else {
    if (array.length === 0) throw new TypeError("Reduce of empty array with no initial value");
    acc = array[0];
    i = 1;
  }
  for (; i < array.length; i++) acc = callback(acc, array[i], i, array);
  return acc;
}

questions.starter_code:
function groupBy(items, key) {
  // Return { [value of item[key]]: [items with that value] }.
}

questions.solution:
function groupBy(items, key) {
  const groups = {};
  for (const item of items) {
    const value = item[key];
    if (!groups[value]) groups[value] = [];
    groups[value].push(item);
  }
  return groups;
}

questions.starter_code:
function unique(array) {
  // Return a new array with each value once, in first-seen order.
}

questions.solution:
function unique(array) {
  return [...new Set(array)];
}

questions.starter_code:
function chunk(array, size) {
  // Return an array of groups, each with up to `size` items.
}

questions.solution:
function chunk(array, size) {
  const result = [];
  for (let i = 0; i < array.length; i += size) {
    result.push(array.slice(i, i + size));
  }
  return result;
}

questions.starter_code:
function flatten(array) {
  // Return a new array with no nested arrays left.
}

questions.solution:
function flatten(array) {
  const result = [];
  for (const item of array) {
    if (Array.isArray(item)) result.push(...flatten(item));
    else result.push(item);
  }
  return result;
}

questions.starter_code:
function countBy(array) {
  // Return { value: number of times it appears }.
}

questions.solution:
function countBy(array) {
  const counts = {};
  for (const value of array) counts[value] = (counts[value] || 0) + 1;
  return counts;
}

questions.starter_code:
function once(fn) {
  // Return a function that runs fn only the first time.
}

questions.solution:
function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

questions.starter_code:
function memoize(fn) {
  // Return a function that remembers fn's result for each argument.
}

questions.solution:
function memoize(fn) {
  const cache = new Map();
  return (arg) => {
    if (!cache.has(arg)) cache.set(arg, fn(arg));
    return cache.get(arg);
  };
}

questions.starter_code:
function debounce(fn, delay) {
  // Return a function that runs fn only after calls stop for `delay` ms.
}

questions.solution:
function debounce(fn, delay) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

questions.starter_code:
function throttle(fn, delay) {
  // Return a function that runs fn at most once every `delay` ms.
}

questions.solution:
function throttle(fn, delay) {
  let last = -Infinity;
  return function (...args) {
    const now = Date.now();
    if (now - last >= delay) {
      last = now;
      return fn.apply(this, args);
    }
  };
}

questions.starter_code:
function curry(fn) {
  // Collect arguments until there are fn.length of them, then call fn.
}

questions.solution:
function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) return fn.apply(this, args);
    return (...more) => curried.apply(this, [...args, ...more]);
  };
}

questions.starter_code:
Function.prototype.myBind = function (thisArg, ...args) {
  // Return a new function with `this` fixed to thisArg and args preset.
};

questions.solution:
Function.prototype.myBind = function (thisArg, ...preset) {
  const fn = this;
  return function (...args) {
    return fn.apply(thisArg, [...preset, ...args]);
  };
};

questions.starter_code:
function deepClone(value) {
  // Copy every level of objects and arrays.
}

questions.solution:
function deepClone(value) {
  if (value === null || typeof value !== "object") return value;
  if (Array.isArray(value)) return value.map(deepClone);
  const copy = {};
  for (const key of Object.keys(value)) copy[key] = deepClone(value[key]);
  return copy;
}

questions.starter_code:
function deepEqual(a, b) {
  // Compare primitives directly, and objects and arrays key by key.
}

questions.solution:
function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  return keysA.every((k) => Object.prototype.hasOwnProperty.call(b, k) && deepEqual(a[k], b[k]));
}

questions.starter_code:
function compose(...fns) {
  // Run the functions right to left.
}

function pipe(...fns) {
  // Run the functions left to right.
}

questions.solution:
function compose(...fns) {
  return pipe(...fns.slice().reverse());
}

function pipe(...fns) {
  return (...args) => {
    if (fns.length === 0) return args[0];
    let result = fns[0](...args);
    for (let i = 1; i < fns.length; i++) result = fns[i](result);
    return result;
  };
}

questions.starter_code:
function promiseAll(promises) {
  // Resolve with every result in input order; reject on the first error.
}

questions.solution:
function promiseAll(promises) {
  return new Promise((resolve, reject) => {
    const results = new Array(promises.length);
    let left = promises.length;
    if (left === 0) return resolve([]);
    promises.forEach((p, i) => {
      Promise.resolve(p).then((value) => {
        results[i] = value;
        left--;
        if (left === 0) resolve(results);
      }, reject);
    });
  });
}

questions.starter_code:
function promiseAllSettled(promises) {
  // Wait for every promise and report each one's status.
}

questions.solution:
function promiseAllSettled(promises) {
  return new Promise((resolve) => {
    const results = new Array(promises.length);
    let left = promises.length;
    if (left === 0) return resolve([]);
    promises.forEach((p, i) => {
      Promise.resolve(p)
        .then(
          (value) => { results[i] = { status: "fulfilled", value }; },
          (reason) => { results[i] = { status: "rejected", reason }; },
        )
        .then(() => {
          left--;
          if (left === 0) resolve(results);
        });
    });
  });
}

questions.starter_code:
function promiseRace(promises) {
  // Settle like the first promise to settle.
}

function promiseAny(promises) {
  // Resolve with the first success; reject with an AggregateError if all fail.
}

questions.solution:
function promiseRace(promises) {
  return new Promise((resolve, reject) => {
    for (const p of promises) Promise.resolve(p).then(resolve, reject);
  });
}

function promiseAny(promises) {
  return new Promise((resolve, reject) => {
    const errors = new Array(promises.length);
    let left = promises.length;
    if (left === 0) return reject(new AggregateError([], "All promises were rejected"));
    promises.forEach((p, i) => {
      Promise.resolve(p).then(resolve, (error) => {
        errors[i] = error;
        left--;
        if (left === 0) reject(new AggregateError(errors, "All promises were rejected"));
      });
    });
  });
}

questions.starter_code:
function retry(fn, times, delay) {
  // Try fn up to `times` times, waiting `delay` ms between failed tries.
}

questions.solution:
async function retry(fn, times, delay) {
  let lastError;
  for (let attempt = 1; attempt <= times; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt < times) await new Promise((r) => setTimeout(r, delay));
    }
  }
  throw lastError;
}

questions.starter_code:
class EventEmitter {
  on(event, listener) {}

  off(event, listener) {}

  once(event, listener) {}

  emit(event, ...args) {}
}

questions.solution:
class EventEmitter {
  listeners = {};

  on(event, listener) {
    (this.listeners[event] ??= []).push(listener);
    return this;
  }

  off(event, listener) {
    const list = this.listeners[event] ?? [];
    this.listeners[event] = list.filter((l) => l !== listener && l.original !== listener);
    return this;
  }

  once(event, listener) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      listener(...args);
    };
    wrapper.original = listener;
    return this.on(event, wrapper);
  }

  emit(event, ...args) {
    const list = [...(this.listeners[event] ?? [])];
    for (const listener of list) listener(...args);
    return list.length > 0;
  }
}

questions.starter_code:
function get(object, path, defaultValue) {
  // Walk the path step by step; return defaultValue if a step is missing.
}

questions.solution:
function get(object, path, defaultValue) {
  let current = object;
  for (const key of path.split(".")) {
    if (current === null || current === undefined) return defaultValue;
    current = current[key];
  }
  return current === undefined ? defaultValue : current;
}

questions.starter_code:
function runWithLimit(tasks, limit) {
  // Run at most `limit` tasks at once; resolve with results in input order.
}

questions.solution:
function runWithLimit(tasks, limit) {
  return new Promise((resolve, reject) => {
    const results = new Array(tasks.length);
    let next = 0;
    let done = 0;
    if (tasks.length === 0) return resolve([]);

    function startNext() {
      if (next >= tasks.length) return;
      const i = next++;
      Promise.resolve()
        .then(tasks[i])
        .then((value) => {
          results[i] = value;
          done++;
          if (done === tasks.length) resolve(results);
          else startNext();
        }, reject);
    }

    for (let k = 0; k < Math.min(limit, tasks.length); k++) startNext();
  });
}

questions.starter_code:
function debounce(fn, delay, options = {}) {
  // options: { leading = false, trailing = true }. Also add debounced.cancel().
}

questions.solution:
function debounce(fn, delay, { leading = false, trailing = true } = {}) {
  let timer = null;
  let pendingArgs = null;
  let pendingThis = null;

  function debounced(...args) {
    const callNow = leading && timer === null;
    pendingArgs = args;
    pendingThis = this;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (trailing && pendingArgs) fn.apply(pendingThis, pendingArgs);
      pendingArgs = null;
    }, delay);
    if (callNow) {
      pendingArgs = null;
      fn.apply(this, args);
    }
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
    pendingArgs = null;
  };
  return debounced;
}

questions.starter_code:
class LRUCache {
  constructor(capacity) {}

  get(key) {}

  put(key, value) {}
}

questions.solution:
class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map();
  }

  get(key) {
    if (!this.map.has(key)) return -1;
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }

  put(key, value) {
    this.map.delete(key);
    this.map.set(key, value);
    if (this.map.size > this.capacity) this.map.delete(this.map.keys().next().value);
  }
}

questions.starter_code:
class MyPromise {
  constructor(executor) {}

  then(onFulfilled, onRejected) {}

  catch(onRejected) {}
}

questions.solution:
class MyPromise {
  constructor(executor) {
    this.state = "pending";
    this.value = undefined;
    this.handlers = [];
    let locked = false;

    const settle = (state, value) => {
      if (this.state !== "pending") return;
      this.state = state;
      this.value = value;
      this.handlers.forEach((run) => run());
      this.handlers = [];
    };
    const resolve = (value) => {
      if (locked) return;
      locked = true;
      if (value && typeof value.then === "function") {
        value.then(
          (v) => { locked = false; resolve(v); },
          (e) => settle("rejected", e),
        );
      } else {
        settle("fulfilled", value);
      }
    };
    const reject = (reason) => {
      if (locked) return;
      locked = true;
      settle("rejected", reason);
    };

    try {
      executor(resolve, reject);
    } catch (error) {
      reject(error);
    }
  }

  then(onFulfilled, onRejected) {
    return new MyPromise((resolve, reject) => {
      const run = () => {
        queueMicrotask(() => {
          const fulfilled = this.state === "fulfilled";
          const handler = fulfilled ? onFulfilled : onRejected;
          if (typeof handler !== "function") {
            (fulfilled ? resolve : reject)(this.value);
            return;
          }
          try {
            resolve(handler(this.value));
          } catch (error) {
            reject(error);
          }
        });
      };
      if (this.state === "pending") this.handlers.push(run);
      else run();
    });
  }

  catch(onRejected) {
    return this.then(undefined, onRejected);
  }
}

questions.starter_code:
function deepClone(value) {
  // Copy every level, and reuse copies for objects you have already seen.
}

questions.solution:
function deepClone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== "object") return value;
  if (seen.has(value)) return seen.get(value);
  const copy = Array.isArray(value) ? [] : {};
  seen.set(value, copy);
  for (const key of Object.keys(value)) copy[key] = deepClone(value[key], seen);
  return copy;
}

questions.starter_code:
function flattenObject(obj) {
  // Return one flat object with dotted keys.
}

questions.solution:
function flattenObject(obj, prefix = "", out = {}) {
  for (const [key, value] of Object.entries(obj)) {
    const path = prefix ? prefix + "." + key : key;
    if (value !== null && typeof value === "object" && !Array.isArray(value)) flattenObject(value, path, out);
    else out[path] = value;
  }
  return out;
}

questions.starter_code:
function createStore(reducer, initialState) {
  // Return { getState, dispatch, subscribe }.
}

questions.solution:
function createStore(reducer, initialState) {
  let state = initialState;
  let listeners = [];
  return {
    getState: () => state,
    dispatch(action) {
      state = reducer(state, action);
      listeners.forEach((listener) => listener());
      return action;
    },
    subscribe(listener) {
      listeners.push(listener);
      return () => {
        listeners = listeners.filter((l) => l !== listener);
      };
    },
  };
}
